1	export type Scenario = {
2	  customer: { yearsWithMHPCO: number };
3	  steps: Step[];
4	};
5	
6	export type Step =
7	  | { op: "quote"; items: Item[] }
8	  | { op: "claim"; policy: number; incident: Incident };
9	
10	export type Item = {
11	  type: string;
12	  material?: string;
13	  enchantment?: number;
14	  cursed?: boolean;
15	};
16	
17	export type Incident = {
18	  cause: string;
19	  damages: Damage[];
20	};
21	
22	export type Damage = {
23	  itemType: string;
24	  amount: number;
25	};
26	
27	export type Result = { premium: number } | { payout: number; remainingCap: number };
28	
29	const PROCESSING_FEE = 5;
30	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
31	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
32	  sword: 100,
33	  amulet: 60,
34	  staff: 80,
35	};
36	
37	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
38	
39	const quoteFor = (items: Item[]): Result => {
40	  const policyBase = items.reduce((sum, item) => sum + basePremiumOf(item), 0);
41	  return {
42	    premium: policyBase + policyBase * FIRST_INSURANCE_SURCHARGE_RATE + PROCESSING_FEE,
43	  };
44	};
45	
46	const resultFor = (step: Step): Result => {
47	  if (step.op === "quote") return quoteFor(step.items);
48	  throw new Error(`unsupported step: ${step.op}`);
49	};
50	
51	export const runScenario = (scenario: Scenario): { results: Result[] } => ({
52	  results: scenario.steps.map(resultFor),
53	});
54

