5	  // Simplest case
6	  it("empty item list → premium 5 G (only the processing fee)", () => {
7	    const result = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    });
11	
12	    expect(result.results).toEqual([{ premium: 5 }]);
13	  });
14	
15	  // Base premiums per item type (with first insurance surcharge + fee)
16	  it("a single sword → base premium 100 G", () => {
17	    const result = runScenario({
18	      customer: { yearsWithMHPCO: 0 },
19	      steps: [{ op: "quote", items: [{ type: "sword" }] }],
20	    });
21	
22	    // 100 base + 10 first insurance + 5 fee
23	    expect(result.results).toEqual([{ premium: 115 }]);
24	  });
25	  it("a single amulet → base premium 60 G", () => {
26	    const result = runScenario({
27	      customer: { yearsWithMHPCO: 0 },
28	      steps: [{ op: "quote", items: [{ type: "amulet" }] }],
29	    });
30	
31	    // 60 base + 6 first insurance + 5 fee
32	    expect(result.results).toEqual([{ premium: 71 }]);
33	  });
34	  it("a single staff → base premium 80 G", () => {
35	    const result = runScenario({
36	      customer: { yearsWithMHPCO: 0 },
37	      steps: [{ op: "quote", items: [{ type: "staff" }] }],
38	    });
39	
40	    // 80 base + 8 first insurance + 5 fee
41	    expect(result.results).toEqual([{ premium: 93 }]);
42	  });
43	  it.todo("a single potion → base premium 40 G");
44	  it.todo("a single rune (component) → base premium 25 G");
45	  it.todo("a single moonstone (component) → base premium 25 G");
46	
47	  // Building block of 3 alike components
48	  it.todo("2 runes → 50 G base premium");
49	  it.todo("3 runes → 60 G base premium (block applies)");
50	  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
51	  it.todo("7 runes → 175 G base premium");
52	
53	  // "Alike" components means exactly the same type
54	  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
55	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
56	
57	  // Item-specific modifiers
58	  it.todo("cursed sword → 50 % risk surcharge on that item's base premium");
59	  it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies");
60	  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
61	  it.todo("cursed sword with exactly enchantment 5 → both surcharges apply");
62	
63	  // Policy-wide modifiers
64	  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
65	  it.todo("customer with 1 year with MHPCO → no loyalty discount");
66	  it.todo("first quote in a scenario → 10 % first insurance surcharge on the policy base");
67	  it.todo("second quote in a scenario → 15 % follow-up contract discount");
68	  it.todo("first insurance surcharge still applies on a follow-up contract");
69	
70	  // Modifier scope on multi-item policies
71	  it.todo(
72	    "cursed sword (100 G) + plain amulet (60 G) → policy base 160 G, curse adds 50 G (of the cursed item only) → 210 G before further modifiers and fee",
73	  );
74	
75	  // Rounding
76	  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
77	  it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
78	
79	  // Integration examples
80	  it.todo(
81	    "newcomer (0 years, no previous contract) with a cursed steel sword enchantment 3 → premium 165 G",
82	  );
83	  it.todo(
84	    "long-standing customer (3 years), second quote, cursed steel sword enchantment 7 → premium 160 G",
